 // Legal page keys
 legalCguTitle: 'Allgemeine Nutzungsbedingungen',
 legalLastUpdated: 'Letzte Aktualisierung:',
 legalDateDec2024: 'Dezember 2025',
 legalDateFeb2026: 'Februar 2026',
 legalDateMar2026: 'März 2026',
 legalDateApr2026: 'April 2026',
 legalCgu1Title: '1. Gegenstand und Annahme',
 legalCgu1Text: 'Diese Allgemeinen Nutzungsbedingungen regeln den Zugang zu und die Nutzung von SpotHitch, einer Community-Plattform für Tramper. Durch den Zugriff auf SpotHitch oder die Erstellung eines Kontos akzeptierst du diese Bedingungen vorbehaltlos. Wenn du nicht zustimmst, nutze die Anwendung bitte nicht.',
 legalCgu2Title: '2. Beschreibung des Dienstes',
 legalCgu2Text: 'SpotHitch ist eine Progressive Web App (PWA), die Trampern ermöglicht: Tramper-Spots über eine interaktive Karte zu teilen und zu entdecken, Spots zu bewerten und zu kommentieren, über die Nachrichtenfunktion mit der Community zu kommunizieren, Reisen zu planen, den Wächter-Modus für die Reisesicherheit zu nutzen und auf den SOS-Button in Notfällen zuzugreifen.',
 legalCgu3Title: '3. Zugangsbedingungen',
 legalCgu3Text: 'Der Zugang zur Karte und die Ansicht von Spots sind frei. Die Erstellung eines Kontos ist erforderlich, um beizutragen (Spots hinzufügen, Bewertungen abgeben, Nachrichten senden). Der Nutzer muss mindestens 16 Jahre alt sein. Minderjährige von 16 bis 18 Jahren benötigen die Genehmigung ihres Erziehungsberechtigten.',
 legalCgu4Title: '4. Benutzerkonto',
 legalCgu4Text: 'Die Registrierung ist kostenlos. Der Nutzer ist für die Vertraulichkeit seiner Zugangsdaten und alle Aktivitäten von seinem Konto aus verantwortlich. Bei Verdacht auf betrügerische Nutzung muss der Nutzer SpotHitch umgehend unter contact@spothitch.com informieren. SpotHitch behält sich das Recht vor, jedes Konto zu sperren oder zu löschen, das gegen diese Bedingungen verstößt.',
 legalCgu5Title: '5. Nutzerinhalte',
 legalCgu5Intro: 'Nutzer können Spots, Bewertungen, Fotos und Nachrichten veröffentlichen. Mit der Veröffentlichung von Inhalten:',
 legalCgu5Item1: 'Garantiert der Nutzer, dass er die nötigen Rechte an den veröffentlichten Inhalten besitzt',
 legalCgu5Item2: 'Erteilt er SpotHitch eine nicht-exklusive, weltweite, kostenlose Lizenz zur Anzeige, Vervielfältigung und Verbreitung der Inhalte im Rahmen des Dienstes',
 legalCgu5Item3: 'Bleibt er für seine veröffentlichten Inhalte verantwortlich und verpflichtet sich, keine illegalen, diffamierenden, hasserfüllten oder irreführenden Inhalte zu veröffentlichen',
 legalCgu5Item4: 'Akzeptiert er, dass Spots und Bewertungen nach Kontolöschung (anonymisiert) sichtbar bleiben, um die Integrität der Community-Datenbank zu bewahren',
 legalCgu6Title: '6. Moderationsrichtlinie (DSA-Konformität)',
 legalCgu6Text: 'SpotHitch moderiert Inhalte gemäß der EU-Verordnung über digitale Dienste (DSA). Offensichtlich illegale Inhalte (Hassrede, Belästigung, CSAM) werden innerhalb von 24 Stunden nach Meldung entfernt. Andere gemeldete Inhalte (Spam, irreführende Informationen, Regelverstöße) werden innerhalb von 7 Tagen bearbeitet. Nutzer, deren Inhalte entfernt werden, werden mit Angabe des Grundes benachrichtigt.',
 legalCgu7Title: '7. Beschwerdesystem',
 legalCgu7Text: 'Jeder Nutzer kann eine Moderationsentscheidung anfechten, indem er eine begründete Beschwerde an contact@spothitch.com sendet. SpotHitch verpflichtet sich, innerhalb von 15 Tagen zu antworten. Wenn die Antwort nicht zufriedenstellend ist, kann der Nutzer den benannten Mediator oder die zuständigen Gerichte einschalten.',
 legalCgu8Title: '8. SOS-Haftungsausschluss',
 legalCgu8Text: 'Der SOS-Button ist KEIN Notdienst. Rufen Sie bei unmittelbarer Gefahr die 112 (oder Ihre lokale Notrufnummer) an. SpotHitch garantiert weder die Übermittlung noch den Empfang von SOS-Warnungen. Die SOS-Funktion ermöglicht es, Ihren Standort mit vertrauenswürdigen Kontakten zu teilen, ersetzt aber keinesfalls professionelle Rettungsdienste.',
 legalCgu9Title: '9. Wächter-Modus Haftungsausschluss',
 legalCgu9Text: 'Der Wächter-Modus ist ein Kommunikationstool zum Teilen Ihrer Position und Ihres Status mit einem vertrauenswürdigen Kontakt. Er stellt keine Sicherheitsgarantie dar. Er erfordert eine aktive Internetverbindung. SpotHitch kann nicht für Fehlfunktionen, Verbindungsverlust oder Verzögerungen bei der Informationsübermittlung haftbar gemacht werden.',
 legalCgu10Title: '10. Spots-Haftungsausschluss',
 legalCgu10Text: 'Spots sind Community-Beiträge. SpotHitch überprüft weder deren Richtigkeit noch deren Sicherheit oder Legalität. Bewertungen und Kommentare sind subjektiv. Der Nutzer ist allein verantwortlich für seine Reiseentscheidungen. Informiere dich stets über die lokalen Vorschriften zum Trampen.',
 legalCgu11Title: '11. Trampen-Haftungsausschluss',
 legalCgu11Text: 'Trampen birgt inhärente Risiken. SpotHitch ist eine Community-Informationsplattform und stellt keinesfalls eine Sicherheitsgarantie dar. Nutzer trampen auf eigene Gefahr. SpotHitch empfiehlt, immer eine Vertrauensperson über die Route zu informieren und den Wächter-Modus zu nutzen.',
 legalCgu12Title: '12. Geistiges Eigentum',
 legalCgu12Text: 'Der SpotHitch-Quellcode wird unter einer Open-Source-Lizenz (MIT) veröffentlicht. Nutzerbeiträge (Spots, Bewertungen, Fotos) stehen unter CC BY-SA 4.0 Lizenz, sofern nicht anders angegeben. Die Marke SpotHitch, das Logo und die grafischen Elemente sind Eigentum von SpotHitch und dürfen nicht ohne Genehmigung verwendet werden.',
 legalCgu13Title: '13. Haftungsbeschränkung',
 legalCgu13Text: 'SpotHitch wird "wie besehen" ohne jegliche Gewährleistung bereitgestellt. SpotHitch garantiert nicht die kontinuierliche Verfügbarkeit des Dienstes, die Richtigkeit der von Nutzern veröffentlichten Informationen oder die Sicherheit beim Trampen. SpotHitch haftet in keinem Fall für direkte oder indirekte Schäden, die aus der Nutzung des Dienstes entstehen.',
 legalCgu14Title: '14. Anwendbares Recht und Gerichtsstand',
 legalCgu14Text: 'Diese Bedingungen unterliegen französischem Recht. Im Streitfall sind französische Gerichte zuständig, vorbehaltlich zwingender Verbraucherschutzvorschriften für Einwohner eines EU-Mitgliedstaats.',
 legalCgu15Title: '15. Änderung der Bedingungen',
 legalCgu15Text: 'SpotHitch behält sich das Recht vor, diese Bedingungen zu ändern. Nutzer werden 30 Tage vor Inkrafttreten der Änderungen per In-App-Benachrichtigung informiert. Die weitere Nutzung des Dienstes nach diesem Datum gilt als Annahme der neuen Bedingungen.',
 legalCgu16Title: '16. Streitbeilegung',
 legalCgu16Text: 'Im Streitfall verpflichten sich die Parteien, eine gütliche Lösung zu suchen. Kommt innerhalb von 30 Tagen keine Einigung zustande, kann der Nutzer einen Verbrauchermediator einschalten oder die zuständigen Gerichte anrufen.',
 // Privacy policy keys
