 // Auto-added by quality-gate --fix
 faqGeneral: 'Allgemein',
 faqQ1: 'Was ist SpotHitch?',
 faqA1: 'SpotHitch ist eine Community-App, die Trampern hilft, die besten Tramper-Spots weltweit zu finden und zu teilen.',
 faqQ2: 'Ist die App kostenlos?',
 faqA2: 'Ja, SpotHitch ist 100% kostenlos! Kein Abo, keine aufdringliche Werbung.',
 faqQ3: 'In welchen Ländern ist SpotHitch verfügbar?',
 faqA3: 'Wir decken viele Länder weltweit ab. Wichtige Länder sind Frankreich, Deutschland, Spanien, USA, Kanada, Australien, Neuseeland, Marokko, Türkei und viele mehr.',
 faqQ4: 'Kann ich SpotHitch ohne Konto nutzen?',
 faqA4: 'Ja, du kannst die Karte erkunden und Spots ansehen ohne Konto. Zum Hinzufügen von Spots oder Mitmachen wird ein Konto benötigt.',
 faqQ5: 'Gibt es eine Nutzer-Community?',
 faqA5: 'Ja! Du kannst dem Chat beitreten, Reisegruppen erstellen und Tipps mit anderen Trampern austauschen.',
 faqSpots: 'Spots',
 faqQ6: 'Wie finde ich einen Spot in meiner Nähe?',
 faqA6: 'Öffne die Karte und aktiviere die Standortbestimmung. Nahe Spots werden angezeigt. Du kannst auch nach Spots in einer bestimmten Stadt suchen.',
 faqQ7: 'Wie füge ich einen neuen Spot hinzu?',
 faqA7: 'Tippe auf den + Button unten auf dem Kartenbildschirm. Fülle die Spot-Infos aus (Foto erforderlich, Standort, Beschreibung) und sende ab.',
 faqQ8: 'Was bedeuten die Spot-Farben auf der Karte?',
 faqA8: 'Farben zeigen die Qualität: grün = gut, orange = mittel, rot = schlecht. Cluster gruppieren nahe Spots.',
 faqQ9: 'Wie melde ich einen problematischen Spot?',
 faqA9: 'Öffne die Spot-Details und tippe auf \'Melden\'. Beschreibe das Problem und unser Team prüft es.',
 faqQ10: 'Was ist ein Check-in?',
 faqA10: 'Ein Check-in bestätigt, dass du diesen Spot besucht hast. Es aktualisiert die Daten und bringt dir Daumen.',
 faqSecurity: 'Sicherheit',
 faqQ11: 'Wie funktioniert der SOS-Modus?',
 faqA11: 'Im Notfall aktiviere den SOS-Modus über den roten Button. Dein GPS-Standort wird mit deinen Notfallkontakten geteilt.',
 faqQ12: 'Wie füge ich Notfallkontakte hinzu?',
 faqA12: 'Im SOS-Modus tippe auf \'Kontakt hinzufügen\'. Gib Name und Telefonnummer ein.',
 faqQ13: 'Sind meine Daten sicher?',
 faqA13: 'Ja, wir halten die DSGVO ein. Deine Daten sind verschlüsselt. Du kannst sie jederzeit herunterladen oder löschen.',
 faqQ14: 'Werden Spots überprüft?',
 faqA14: 'Jeder Spot wird zur Überprüfung eingereicht. Community-Bewertungen helfen auch, problematische Spots zu erkennen.',
 faqQ15: 'Sicherheitstipps fürs Trampen?',
 faqA15: 'Informiere jemanden über deine Route, vertraue deinem Instinkt, vermeide Trampen bei Nacht und nutze den SOS-Modus im Zweifelsfall.',
 faqAccount: 'Konto',
 faqQ16: 'Wie erstelle ich ein Konto?',
 faqA16: 'Tippe auf \'Anmelden\' dann \'Konto erstellen\'. Du kannst dich mit E-Mail oder Google registrieren.',
 faqQ17: 'Passwort vergessen?',
 faqA17: 'Tippe auf dem Anmeldebildschirm auf \'Passwort vergessen?\'. Ein Link zum Zurücksetzen wird per E-Mail gesendet.',
 faqQ18: 'Wie lösche ich mein Konto?',
 faqA18: 'Gehe zu Profil > Meine Daten (DSGVO) > Konto löschen. Diese Aktion ist unwiderruflich.',
 faqQ19: 'Wie verdiene ich Daumen?',
 faqA19: 'Füge Spots hinzu (+50), mache Check-ins (+10), hinterlasse Bewertungen (+15) und schließe Challenges ab.',
 faqQ20: 'Wie funktioniert der Vertrauens-Score?',
 faqA20: 'Der Score spiegelt deine Zuverlässigkeit wider: Kontoalter, erstellte Spots, hilfreiche Bewertungen, Identitätsverifizierung und Community-Stimmen.',
 faqTechnical: 'Technisch',
 faqQ21: 'Wie installiere ich die App?',
 faqA21: 'SpotHitch ist eine PWA. Öffne auf deinem Handy die Seite in Chrome/Safari und tippe auf \'Zum Startbildschirm hinzufügen\'.',
 faqQ22: 'Funktioniert die App offline?',
 faqA22: 'Ja! Besuchte Spots werden zwischengespeichert. Aktionen werden bei erneuter Verbindung synchronisiert.',
 faqQ23: 'Verbraucht die App viel Akku?',
 faqA23: 'Nein, SpotHitch ist optimiert. Die Standortbestimmung ist nur aktiv, wenn du sie nutzt.',
 faqQ24: 'Wie ändere ich die Sprache?',
 faqA24: 'Gehe zu Profil > Einstellungen > Sprache. Wähle zwischen Französisch, Englisch, Spanisch oder Deutsch.',
 faqQ25: 'Welche Browser werden unterstützt?',
 faqA25: 'Chrome, Firefox, Safari und Edge. Funktioniert auf iOS 11.3+ und Android 5.0+.',
